update pages set contenu = '{"sections":[]}'::jsonb where path = '/secteurs/logistique/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"heros","h1":"Maintenance des équipements logistiques","mecanisme":"Nous travaillons sur vos indicateurs, pas à côté : disponibilité par zone, récurrence par équipement, respect du plan préventif. Les interventions se calent sur vos vagues de préparation, et l''astreinte couvre les nuits et les week-ends.","cta":"Faire chiffrer la maintenance de mon entrepôt","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30. Astreinte 24/24 et 7/7 en option pour les nuits et les pics."},{"type":"chiffres","chiffres":[{"valeur":"+ 120","libelle":"clients industriels et logisticiens, dont plus de 80 réguliers"},{"valeur":"10 %","libelle":"des candidats retenus, entretien technique et comportemental, résultats partagés"},{"valeur":"4","libelle":"agences, Lyon (siège), Montréal, Dubaï, Madrid, astreinte portée par le hub de techniciens le plus proche"}]},{"type":"probleme","punchline":"Le trieur principal lâche à 16h30. Des milliers de commandes basculent au lendemain, et le client final ne connaît pas vos contraintes techniques.","puces":[{"accroche":"L''expédition sans attendre ne se rattrape pas.","texte":"Une heure perdue en fin d''après-midi se paie en promesses rompues, pas en heures de main d''œuvre."},{"accroche":"Plus le site est automatisé, plus la panne coûte cher.","texte":"Trieurs, transstockeurs, navettes, AGV : la productivité monte, et le prix de l''arrêt avec elle."},{"accroche":"Votre pic concentre l''année sur quelques semaines.","texte":"L''équipement doit être prêt avant, pas réparé pendant."},{"accroche":"Vous rendez des comptes en chiffres.","texte":"Et votre mainteneur actuel vous répond en impressions."},{"accroche":"Les allées sont pleines pendant que vous intervenez.","texte":"Préparateurs, caristes et techniciens partagent le même espace : la coactivité n''est pas une option."}]},{"type":"offre","lignes":[{"prestation":{"accroche":"Préventif calé sur vos heures de fonctionnement réelles","texte":", resserré avant les pics."},"benefice":"Vous entretenez au rythme du flux, pas au rythme d''un calendrier constructeur."},{"prestation":{"accroche":"Priorisation par impact sur l''expédition","texte":"un trieur principal ne se traite pas comme une ligne de délestage."},"benefice":"Le budget maintenance va là où l''arrêt bloque vraiment le quai."},{"prestation":{"accroche":"Mesure et restitution","texte":"disponibilité par zone, temps moyen de remise en service, récurrence par équipement, coût par colis."},"benefice":"Vos revues d''exploitation s''appuient sur des faits. Le gestionnaire voit la capacité, la direction voit le coût."},{"prestation":{"accroche":"Interventions en heures creuses","texte":", tôt le matin, entre deux équipes, de nuit."},"benefice":"Les opérations lourdes ne mangent jamais une vague de préparation."},{"prestation":{"accroche":"Couverture complète du site","texte":"[convoyeurs et tri](/secteurs/logistique/maintenance-convoyeur/), transstockeurs, navettes, quais et portes rapides, pesage, froid et utilités."},"benefice":"Un seul contrat du quai de réception au quai d''expédition, au lieu d''un prestataire par famille."},{"prestation":{"accroche":"Astreinte 24/24 et 7/7 en option","texte":", mobilisation depuis le hub de techniciens le plus proche."},"benefice":"Une panne du dimanche soir ne devient pas un lundi matin sacrifié."},{"prestation":{"accroche":"Conseil de stock minimal de pièces critiques","texte":", dimensionné sur vos historiques et les délais fournisseur."},"benefice":"Une part importante des arrêts longs vient d''une pièce manquante en magasin."}],"prose":[{"texte":"Pour les gros travaux, montage d''une ligne, transfert d''activité, extension de site, notre offre [chantier](/offres/chantier/) prend le relais avec un chef de projet unique, de l''étude à la mise en route. Et la [peak season logistique](/secteurs/logistique/peak-season/) se prépare selon un compte à rebours dédié."}]},{"type":"deroule","etapes":[{"titre":"Audit d''entrée","texte":"état des lieux du parc, analyse des défaillances récurrentes, revue des contrôles réglementaires. Vous obtenez l''état réel de vos installations, zone par zone."},{"titre":"Reprise de l''historique","texte":"récupération des données d''arrêt existantes, connexion à votre GMAO et à vos outils d''exploitation. Pas de système parallèle, pas de double saisie."},{"titre":"Plan priorisé","texte":"fréquences calées sur l''utilisation réelle, points de contrôle par type d''équipement, pièces critiques identifiées."},{"titre":"Mise en service","texte":"plan de prévention, balisage, protection des personnes, coordination avec vos chefs d''équipe. Les règles de coactivité sont écrites avant la première intervention."},{"titre":"Exécution","texte":"préventif en fenêtres creuses, correctif prioritaire, astreinte activée selon le contrat."},{"titre":"Bilan à trois mois","texte":"disponibilité, récurrence, coûts par zone. Si les chiffres ne progressent pas, la conversation est simple."}]},{"type":"garanties","puces":[{"accroche":"La mesure avant l''affirmation","texte":"disponibilité par zone, récurrence par équipement, respect du plan préventif. Vous jugez sur vos propres indicateurs, sans rien croire sur parole."},{"accroche":"Une transition sans interruption de service","texte":"reprise de l''historique, phase de recouvrement, coordination avec vos équipes et, si besoin, avec le prestataire sortant. La chaîne de responsabilité reste nette à chaque instant."},{"accroche":"Un périmètre et des modalités de sortie écrits","texte":"ce qui est inclus, ce qui ne l''est pas, les indicateurs suivis, les conditions d''arrêt. Le cadre protège les deux parties."}]},{"type":"cta","question":"Besoin de savoir où votre entrepôt perd réellement de la capacité ?","bouton":"Faire chiffrer la maintenance de mon entrepôt","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."}]'::jsonb) where path = '/secteurs/logistique/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"preuves","preuves":[{"titre":"10 à 20 techniciens une semaine sur deux, par créneaux de 8 heures, sur un site en continu","texte":"centre logistique ORY4, depuis septembre 2022, contrat annuel","lienLibelle":"Étude de cas AMAZON : maintien d''un centre logistique","lienHref":"/preuves/amazon-centre-logistique/"},{"titre":"Dispositif transposé sur un deuxième site","texte":"10 techniciens polyvalents une semaine par mois, ETZ 2 à Metz, depuis mai 2024","lienLibelle":"Étude de cas AMAZON : démarrage d''un nouveau site","lienHref":"/preuves/amazon-nouveau-site/"},{"titre":"Deux techniciens dédiés à la maintenance curative des convoyeurs, trieurs et packaging, transport","texte":"en poste sur site","lienLibelle":"Étude de cas GLS : maintenance curative","lienHref":"/preuves/gls-maintenance-curative/"},{"titre":"Six techniciens en permanence sur le contrat de préventif annuel des sites de Lyon","texte":"depuis septembre 2023, prise en charge complète en un mois","lienLibelle":"Étude de cas VEEPEE : sites de Lyon","lienHref":"/preuves/veepee-sites-lyon/"},{"titre":"12 monteurs mécaniciens et 8 engins de levage pour le montage d''un centre logistique","texte":"6 semaines de chantier, livraison tenue","lienLibelle":"Étude de cas AKTID : montage d''un centre logistique","lienHref":"/preuves/aktid-centre-logistique/"},{"titre":"Renfort de contrôle de chantier chez un spécialiste de l''automatisation logistique","texte":"intervenants intégrés aux équipes sur des projets stratégiques","lienLibelle":"Étude de cas ALSTEF Group : collaboration","lienHref":"/preuves/alstef-group/"}]},{"type":"objections","questions":[{"question":"Intervenez-vous pendant l''exploitation, au milieu des préparateurs ?","reponse":"Oui, c''est le quotidien du secteur : plan de prévention, balisage, protection des personnes, coordination avec vos chefs d''équipe. Les opérations lourdes se planifient en heures creuses, les contrôles et une part du préventif se réalisent en marche, sur les systèmes qui le permettent."},{"question":"Pouvez-vous couvrir plusieurs sites d''un même réseau ?","reponse":"Oui. Nos 4 agences couvrent la France entière, avec un contrat unique, des comptes rendus au même format et un taux horaire homogène. La logistique multi-sites est l''un de nos terrains naturels : votre entreprise garde un seul interlocuteur."},{"question":"Travaillez-vous avec notre GMAO et nos logiciels d''exploitation ?","reponse":"Oui. Nos comptes rendus s''y intègrent, et nous exploitons vos données d''arrêt pour affiner le plan de maintenance. Pas de système parallèle, pas de double saisie."},{"question":"Que faites-vous que notre mainteneur actuel ne fait pas ?","reponse":"Nous mesurons, et nous montrons : disponibilité, récurrence, coûts par zone. Si un contrat vous lie déjà, nous pouvons démarrer par un périmètre d''essai et laisser les chiffres parler. Le changement de fournisseur se décide sur des faits."},{"question":"Fournissez-vous les pièces détachées ?","reponse":"Nous consultons le marché au prix réel, rouleaux, bandes, moteurs, capteurs, en composants d''origine ou équivalents. Nous vous conseillons un stock minimal de pièces critiques par type d''équipement, dimensionné sur vos historiques de défaillance et les délais fournisseur."},{"question":"Que se passe-t-il en cas de panne un dimanche soir ?","reponse":"L''astreinte 24/24 et 7/7 prend l''appel et mobilise un technicien depuis l''hub de techniciens le plus proche. L''objectif de travail reste le même : rendre la ligne avant l''ouverture de la vague suivante."}]},{"type":"ctaFinal","question":"Besoin de fiabiliser vos flux avant la prochaine montée en charge ?","bouton":"Faire chiffrer la maintenance de mon entrepôt","rappel":"ou appelez le 04 78 33 72 05, rappel dans l''heure aux horaires ouvrés."}]'::jsonb) where path = '/secteurs/logistique/';
